    return matrix_tex(rows)

def answer_matrix(m,t,s,k):
    result=copy.deepcopy(m)
    result[t]=[m[t][j]+k*m[s][j] for j in range(3)]
    return result


def bank(p,profile):
    m,t,s,k = p['matrix'],p['target'],p['source'],p['k']
    other=3-t-s
